export function getTranslatedKomatsuMachineName(model: string, language: string): string {
  const translations = komatsumachineNameTranslations[model];
  if (!translations) return model;
  return translations[language] || translations['en'] || model;
}

export function getTranslatedKomatsuMachineType(model: string, language: string): string {
  const translations = komatsumachineTypeTranslations[model];
  if (!translations) return model;
  return translations[language] || translations['en'] || model;
}

